 13	/// SQLite-backed [`SessionStore`] that persists `task_id ↔ session_id` mappings
 14	/// and a per-task pending-request that is cleared atomically on first read.
 15	pub struct SqliteStore {
 16	    conn: Arc<Mutex<rusqlite::Connection>>,
 17	    // Held for the store's lifetime: an exclusive advisory lock on `<path>.lock`
 18	    // so only one `serve` owns a DB file (makes the boot sweep safe). `None` for
 19	    // in-memory stores.
 20	    _lock: Option<std::fs::File>,
 21	}
 22	
 23	impl SqliteStore {
 24	    /// Open an in-memory database (suitable for tests).
 25	    pub fn open_in_memory() -> Result<Self, BridgeError> {
 26	        let conn = rusqlite::Connection::open_in_memory().map_err(|_| BridgeError::StoreFailure)?;
 27	        conn.execute_batch("PRAGMA foreign_keys = ON;")
 28	            .map_err(|_| BridgeError::StoreFailure)?;
 29	        let store = Self {
 30	            conn: Arc::new(Mutex::new(conn)),
 31	            _lock: None,
 32	        };
 33	        store.create_schema()?;
 34	        Ok(store)
 35	    }
 36	
 37	    /// Open a file-backed DB, acquiring an exclusive advisory lock on `<path>.lock`.
 38	    /// A second `open` of the same path while the first is held returns an error —
 39	    /// this single-serve-per-DB guarantee is what makes the boot `sweep_interrupted`
 40	    /// safe (it can never flip a live serve's `Working` rows).
 41	    pub fn open(path: &std::path::Path) -> Result<Self, BridgeError> {
 42	        use fs2::FileExt;
 43	        // The store path may name a not-yet-created subdir (e.g. a `[store] path` of
 44	        // `<config-dir>/.a2a-bridge/tasks.sqlite`); neither the lock-file open nor sqlite will
 45	        // create it, so `mkdir -p` the parent first or `open` fails with StoreFailure.
 46	        if let Some(parent) = path.parent() {
 47	            if !parent.as_os_str().is_empty() {
 48	                std::fs::create_dir_all(parent).map_err(|_| BridgeError::StoreFailure)?;
 49	            }
 50	        }
 51	        let lock_path = {
 52	            let mut p = path.as_os_str().to_os_string();
 53	            p.push(".lock");
 54	            std::path::PathBuf::from(p)
 55	        };
 56	        let lock = std::fs::OpenOptions::new()
 57	            .create(true)
 58	            .write(true)
 59	            .truncate(false)
 60	            .open(&lock_path)
 61	            .map_err(|_| BridgeError::StoreFailure)?;
 62	        lock.try_lock_exclusive()
 63	            .map_err(|_| BridgeError::StoreFailure)?;
 64	        let conn = rusqlite::Connection::open(path).map_err(|_| BridgeError::StoreFailure)?;
 65	        conn.execute_batch("PRAGMA foreign_keys = ON;")
 66	            .map_err(|_| BridgeError::StoreFailure)?;
 67	        let store = Self {
 68	            conn: Arc::new(Mutex::new(conn)),
 69	            _lock: Some(lock),
 70	        };
 71	        store.create_schema()?;
 72	        Ok(store)
 73	    }
