        item_id: None,
    })
    .await
    .unwrap();
    use bridge_core::ids::NodeId;
    use bridge_core::task_store::ResumeClaim;
    s.put_node_checkpoint(&t, &NodeId::parse("codex").unwrap(), "OUT", true, 2)
